const input = items[0].json;
const sources = Array.isArray(input.sources) ? input.sources : [];
return sources.map((source, index) => ({
  json: { index, source, title: input.title, spaceKey: input.spaceKey, template: input.template, mode: input.mode, pageUrl: input.pageUrl, instructions: input.instructions, confluenceBaseUrl: input.confluenceBaseUrl, notify: input.notify, mattermostChannelId: input.mattermostChannelId, senderEmail: input.senderEmail, parentPageId: input.parentPageId },
}));

const sorted = items.map(i => i.json).sort((a, b) => a.index - b.index);
const input = sorted[0];
const sourceText = sorted.map(i => i.text).join('\n\n');
return [{ json: { title: input.title, spaceKey: input.spaceKey, template: input.template, mode: input.mode, pageUrl: input.pageUrl, instructions: input.instructions, confluenceBaseUrl: input.confluenceBaseUrl, notify: input.notify, mattermostChannelId: input.mattermostChannelId, senderEmail: input.senderEmail, parentPageId: input.parentPageId, sourceText } }];

const url = $json.pageUrl || '';
const match = url.match(/\/pages\/(\d+)\/?/);
return [{ json: { ...$json, pageId: match ? match[1] : '' } }];

